00150     protected function replaceAll($params)
00151     {
00152         $content = file_get_contents( $this->bearsamppConf );
00153 
00154         foreach ( $params as $key => $value ) {
00155             $content                      = preg_replace( '|' . $key . ' = .*|', $key . ' = ' . '"' . $value . '"', $content );
00156             $this->bearsamppConfRaw[$key] = $value;
00157             switch ( $key ) {
00158                 case self::LOCAL_CFG_PORT:
00159                     $this->port = $value;
00160                     break;
00161                 case self::LOCAL_CFG_ROOT_USER:
00162                     $this->rootUser = $value;
00163                     break;
00164                 case self::LOCAL_CFG_ROOT_PWD:
00165                     $this->rootPwd = $value;
00166                     break;
00167             }
00168         }
00169 
00170         file_put_contents( $this->bearsamppConf, $content );
00171     }
