00221     public function checkPort($port, $showWindow = false)
00222     {
00223         global $bearsamppLang, $bearsamppWinbinder;
00224         $boxTitle = sprintf( $bearsamppLang->getValue( Lang::CHECK_PORT_TITLE ), $this->getName(), $port );
00225 
00226         if ( !Util::isValidPort( $port ) ) {
00227             Log::error( $this->getName() . ' port not valid: ' . $port );
00228 
00229             return false;
00230         }
00231 
00232         $fp = @fsockopen( '127.0.0.1', $port, $errno, $errstr, 5 );
00233         if ( $fp ) {
00234             if ( version_compare( phpversion(), '5.3' ) === -1 ) {
00235                 $dbLink = mysqli_connect( '127.0.0.1', $this->rootUser, $this->rootPwd, '', $port );
00236             }
00237             else {
00238                 $dbLink = mysqli_connect( '127.0.0.1:' . $port, $this->rootUser, $this->rootPwd );
00239             }
00240             $isMariadb = false;
00241             $version   = false;
00242 
00243             if ( $dbLink ) {
00244                 $result = mysqli_query( $dbLink, 'SHOW VARIABLES' );
00245                 if ( $result ) {
00246                     while ( false !== ($row = mysqli_fetch_array( $result, MYSQLI_NUM )) ) {
00247                         if ( $row[0] == 'version' ) {
00248                             $version = explode( '-', $row[1] );
00249                             $version = count( $version ) > 1 ? $version[0] : $row[1];
00250                         }
00251                         if ( $row[0] == 'version_comment' && UtilString::startWith( strtolower( $row[1] ), 'mariadb' ) ) {
00252                             $isMariadb = true;
00253                         }
00254                         if ( $isMariadb && $version !== false ) {
00255                             break;
00256                         }
00257                     }
00258                     if ( !$isMariadb ) {
00259                         Log::debug( $this->getName() . ' port used by another DBMS: ' . $port );
00260                         if ( $showWindow ) {
00261                             $bearsamppWinbinder->messageBoxWarning(
00262                                 sprintf( $bearsamppLang->getValue( Lang::PORT_USED_BY_ANOTHER_DBMS ), $port ),
00263                                 $boxTitle
00264                             );
00265                         }
00266                     }
00267                     else {
00268                         Log::debug( $this->getName() . ' port ' . $port . ' is used by: ' . $this->getName() . ' ' . $version );
00269                         if ( $showWindow ) {
00270                             $bearsamppWinbinder->messageBoxInfo(
00271                                 sprintf( $bearsamppLang->getValue( Lang::PORT_USED_BY ), $port, $this->getName() . ' ' . $version ),
00272                                 $boxTitle
00273                             );
00274                         }
00275 
00276                         return true;
00277                     }
00278                 }
00279                 mysqli_close( $dbLink );
00280             }
00281             else {
00282                 Log::debug( $this->getName() . ' port ' . $port . ' is used by another application' );
00283                 if ( $showWindow ) {
00284                     $bearsamppWinbinder->messageBoxWarning(
00285                         sprintf( $bearsamppLang->getValue( Lang::PORT_NOT_USED_BY ), $port ),
00286                         $boxTitle
00287                     );
00288                 }
00289             }
00290         }
00291         else {
00292             Log::debug( $this->getName() . ' port ' . $port . ' is not used' );
00293             if ( $showWindow ) {
00294                 $bearsamppWinbinder->messageBoxError(
00295                     sprintf( $bearsamppLang->getValue( Lang::PORT_NOT_USED ), $port ),
00296                     $boxTitle
00297                 );
00298             }
00299         }
00300 
00301         return false;
00302     }
