00313     public function changeRootPassword($currentPwd, $newPwd, $wbProgressBar = null)
00314     {
00315         global $bearsamppWinbinder;
00316         $error = null;
00317 
00318         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00319         if ( version_compare( phpversion(), '5.3' ) === -1 ) {
00320             $dbLink = @mysqli_connect( '127.0.0.1', $this->rootUser, $currentPwd, '', $this->port );
00321         }
00322         else {
00323             $dbLink = @mysqli_connect( '127.0.0.1:' . $this->port, $this->rootUser, $currentPwd );
00324         }
00325         if ( !$dbLink ) {
00326             $error = mysqli_connect_error();
00327         }
00328 
00329         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00330         $stmt = @mysqli_prepare( $dbLink, 'UPDATE mysql.user SET Password=PASSWORD(?) WHERE User=?' );
00331         if ( empty( $error ) && $stmt === false ) {
00332             $error = mysqli_error( $dbLink );
00333         }
00334 
00335         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00336         if ( empty( $error ) && !@mysqli_stmt_bind_param( $stmt, 'ss', $newPwd, $this->rootUser ) ) {
00337             $error = mysqli_stmt_error( $stmt );
00338         }
00339 
00340         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00341         if ( empty( $error ) && !@mysqli_stmt_execute( $stmt ) ) {
00342             $error = mysqli_stmt_error( $stmt );
00343         }
00344 
00345         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00346         if ( $stmt !== false ) {
00347             mysqli_stmt_close( $stmt );
00348         }
00349 
00350         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00351         if ( empty( $error ) && @mysqli_query( $dbLink, 'FLUSH PRIVILEGES' ) === false ) {
00352             $error = mysqli_error( $dbLink );
00353         }
00354 
00355         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00356         if ( $dbLink ) {
00357             mysqli_close( $dbLink );
00358         }
00359 
00360         if ( !empty( $error ) ) {
00361             return $error;
00362         }
00363 
00364         // bearsampp.conf
00365         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00366         $this->setRootPwd( $newPwd );
00367 
00368         // conf
00369         $this->update();
00370         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00371 
00372         return true;
00373     }
