00436     protected function updateConfig($version = null, $sub = 0, $showWindow = false) {
00437         global $bearsamppLang, $bearsamppApps, $bearsamppWinbinder;
00438 
00439         if (!$this->enable) {
00440             return true;
00441         }
00442 
00443         $version = $version == null ? $this->version : $version;
00444         Log::debug(($sub > 0 ? str_repeat(' ', 2 * $sub) : '') . 'Update ' . $this->name . ' ' . $version . ' config');
00445 
00446         $boxTitle = sprintf($bearsamppLang->getValue(Lang::SWITCH_VERSION_TITLE), $this->getName(), $version);
00447 
00448         $conf = str_replace('mariadb' . $this->getVersion(), 'mariadb' . $version, $this->getConf());
00449         $bearsamppConf = str_replace('mariadb' . $this->getVersion(), 'mariadb' . $version, $this->bearsamppConf);
00450 
00451         if (!file_exists($conf) || !file_exists($bearsamppConf)) {
00452             Log::error('bearsampp config files not found for ' . $this->getName() . ' ' . $version);
00453             if ($showWindow) {
00454                 $bearsamppWinbinder->messageBoxError(
00455                     sprintf($bearsamppLang->getValue(Lang::BEARSAMPP_CONF_NOT_FOUND_ERROR), $this->getName() . ' ' . $version),
00456                     $boxTitle
00457                 );
00458             }
00459             return false;
00460         }
00461 
00462         $bearsamppConfRaw = parse_ini_file($bearsamppConf);
00463         if ($bearsamppConfRaw === false || !isset($bearsamppConfRaw[self::ROOT_CFG_VERSION]) || $bearsamppConfRaw[self::ROOT_CFG_VERSION] != $version) {
00464             Log::error('bearsampp config file malformed for ' . $this->getName() . ' ' . $version);
00465             if ($showWindow) {
00466                 $bearsamppWinbinder->messageBoxError(
00467                     sprintf($bearsamppLang->getValue(Lang::BEARSAMPP_CONF_MALFORMED_ERROR), $this->getName() . ' ' . $version),
00468                     $boxTitle
00469                 );
00470             }
00471             return false;
00472         }
00473 
00474         // bearsampp.conf
00475         $this->setVersion($version);
00476 
00477         // conf
00478         Util::replaceInFile($this->getConf(), array(
00479             '/^port(.*?)=(.*?)(\d+)/' => 'port = ' . $this->port
00480         ));
00481 
00482         // phpmyadmin
00483         $bearsamppApps->getPhpmyadmin()->update($sub + 1);
00484 
00485         return true;
00486     }
00495 public function getCmdLineOutput($cmd) {
00496     $result = array(
00497         'syntaxOk' => false,
00498         'content'  => null,
00499     );
00500 
00501     $bin = $this->getExe();
00502     $removeLines = 0;
00503     $outputFrom = '';
00504     if ($cmd == self::CMD_SYNTAX_CHECK) {
00505         $outputFrom = '2';
00506     } elseif ($cmd == self::CMD_VARIABLES) {
00507         $bin = $this->getAdmin();
00508         $cmd .= ' --user=' . $this->getRootUser();
00509         if ($this->getRootPwd()) {
00510             $cmd .= ' --password=' . $this->getRootPwd();
00511         }
00512         $removeLines = 2;
00513     }
00514 
00515     if (file_exists($bin)) {
00516         $tmpResult = Batch::exec('mariadbGetCmdLineOutput', '"' . $bin . '" ' . $cmd . ' ' . $outputFrom, 5);
00517         if ($tmpResult !== false && is_array($tmpResult)) {
00518             $result['syntaxOk'] = empty($tmpResult) || !UtilString::contains(trim($tmpResult[count($tmpResult) - 1]), '[ERROR]');
00519             for ($i = 0; $i < $removeLines; $i++) {
00520                 unset($tmpResult[$i]);
00521             }
00522             $result['content'] = trim(str_replace($bin, '', implode(PHP_EOL, $tmpResult)));
00523         }
00524     }
00525 
00526     return $result;
00527 }
