00701 public function initData($path = null, $version = null)
00702 {
00703     Log::trace( 'Starting MariaDB data initialization' );
00704     $startTime = microtime( true );
00705 
00706     $path    = $path != null ? $path : Path::getModuleCurrentPath($this);
00707     $version = $version != null ? $version : $this->getVersion();
00708     $dataDir = $path . '/data';
00709 
00710     if ( is_dir( $dataDir . '/mysql' ) ) {
00711         Log::trace( 'MariaDB data directory already initialized' );
00712 
00713         return true;
00714     }
00715 
00716     if ( !is_dir( $dataDir ) ) {
00717         @mkdir( $dataDir, 0777, true );
00718         Log::trace( 'Created MariaDB data directory' );
00719     }
00720 
00721     // Check for init.bat first
00722     if ( file_exists( $path . '/init.bat' ) ) {
00723         Log::trace( 'Initializing MariaDB via init.bat' );
00724         try {
00725             Batch::initializeMariadb( $path );
00726         } catch ( \Throwable $e ) {
00727             Log::trace( 'Error during MariaDB initialization via Batch: ' . $e->getMessage() );
00728 
00729             return false;
00730         }
00731     } else {
00732         // Use mariadb-install-db.exe
00733         Log::trace( 'Initializing MariaDB via mariadb-install-db.exe' );
00734         $installDbExe = $path . '/bin/mariadb-install-db.exe';
00735         if ( !file_exists( $installDbExe ) ) {
00736             $installDbExe = $path . '/bin/mysql_install_db.exe';
00737         }
00738 
00739         if ( file_exists( $installDbExe ) ) {
00740             $cmd = '"' . Path::formatWindowsPath( $installDbExe ) . '"';
00741             $cmd .= ' --datadir="' . Path::formatWindowsPath( $dataDir ) . '"';
00742 
00743             try {
00744                 Batch::exec( 'initializeMariadb', $cmd, 60 );
00745             } catch ( \Throwable $e ) {
00746                 Log::trace( 'Error during MariaDB initialization via mariadb-install-db: ' . $e->getMessage() );
00747 
00748                 return false;
00749             }
00750         } else {
00751             Log::error( 'MariaDB initialization failed: No init.bat or mariadb-install-db.exe found' );
00752 
00753             return false;
00754         }
00755     }
00756 
00757     // Verify initialization
00758     if ( !is_dir( $dataDir . '/mysql' ) ) {
00759         Log::trace( 'MariaDB initialization appears to have failed: mysql directory still missing' );
00760 
00761         return false;
00762     }
00763 
00764     $totalTime = round( microtime( true ) - $startTime, 2 );
00765     Log::trace( "MariaDB initialization completed in {$totalTime}s" );
00766 
00767     return true;
00768 }
00769 }
